package com.bank.dsa;

import java.math.BigDecimal;
import java.util.logging.*;

// Runnable demo: classify net daily movement as +1 (credit), -1 (debit), 0 (flat).
public class CheckNumberDemo {
    private static final Logger log = Logger.getLogger(CheckNumberDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MovementClassifier classifier = new MovementClassifier();

        BigDecimal netMovement = new BigDecimal("-8000.00");  // N: net debit today
        int sign = classifier.sign(netMovement);
        log.info(() -> "Rajesh SAV2001 net movement sign = " + sign
                + (sign > 0 ? " (credit ↑)" : sign < 0 ? " (debit ↓)" : " (flat →)"));
    }
}

// ─── Would be in MovementClassifier.java in a real project ───
class MovementClassifier {
    // Nested decision: N > 0 ? +1 : (N < 0 ? -1 : 0). Implemented with signum.
    int sign(BigDecimal netMovement) {
        if (netMovement == null) {
            throw new IllegalArgumentException("Net movement must not be null");
        }
        if (netMovement.signum() > 0) {       // N > 0 ?
            return 1;
        } else if (netMovement.signum() < 0) { // else N < 0 ?
            return -1;
        } else {
            return 0;                          // N == 0
        }
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
